/**
 * dsh-graphview — Web client (sigma.js viz).
 *
 * Registered as a `settings.section` panel so it renders inside the DSH Web
 * settings tab. The heavy graph projection lives on the host (graph-engine via
 * the /noema-graphview/snapshot route), so this client only fetches, draws,
 * and emits view-control query params. React + react/jsx-runtime are provided
 * by the host via the __ModuleLoader__ factory `require`; sigma + graphology
 * are bundled.
 *
 * SVG export is generated by us (svg-export.ts) because sigma v2 renders to
 * WebGL canvases, which cannot produce SVG; node positions come from our
 * deterministic circular layout, so the export matches the visible layout.
 *
 * Saved named views persist in localStorage via saved-views.ts.
 */
import { useEffect, useMemo, useRef, useState } from 'react'
import type { JSX } from 'react'
import type { CSSProperties } from 'react'
import type { Context as ClientContext } from '@deepseek-ai/cordis'
import { Graph } from 'graphology'
import { Sigma } from 'sigma'
import type { GraphNode, GraphLink } from '../types.js'
import { loadViews, saveView, deleteView, cloneQuery } from './saved-views.js'
import type { SavedView, ViewQuery } from './saved-views.js'
import { circularLayout, toSVG } from './svg-export.js'

export const inject = ['slots', 'locale']

interface Snapshot {
  nodes: GraphNode[]
  links: Array<GraphLink & { implicit?: string }>
  capturedAt: string
  root: string
  implicitEdges: boolean
  error?: string
}

const KIND_COLOR: Record<string, string> = {
  preference: '#eab308', decision: '#3b82f6', constraint: '#ef4444',
  fact: '#22c55e', reference: '#a8a29e', workflow: '#8b5cf6',
  warning: '#f97316', error_fix: '#dc2626',
}

function colorOf(kind: string): string {
  return KIND_COLOR[kind] ?? '#94a3b8'
}

const SNAPSHOT_BASE = '/noema-graphview/snapshot'

export interface ViewQuery {
  kinds: string[]
  tags: string[]
  hiddenLinkTypes: string[]
  implicitEdges: boolean
  hideTombstoned: boolean
  focus: string | null
}

const DEFAULT_VIEW: ViewQuery = {
  kinds: [], tags: [], hiddenLinkTypes: [], implicitEdges: false, hideTombstoned: true, focus: null,
}

export function fetchSnapshot(view: ViewQuery): Promise<Snapshot> {
  const params = new URLSearchParams()
  if (view.kinds.length) params.set('kinds', view.kinds.join(','))
  if (view.tags.length) params.set('tags', view.tags.join(','))
  if (view.hiddenLinkTypes.length) params.set('hiddenLinkTypes', view.hiddenLinkTypes.join(','))
  if (view.implicitEdges) params.set('implicitEdges', 'true')
  if (view.hideTombstoned === false) params.set('hideTombstoned', 'false')
  if (view.focus) params.set('focus', view.focus)
  const qs = params.toString()
  return fetch(SNAPSHOT_BASE + (qs ? '?' + qs : ''))
    .then(r => r.ok ? r.json() as Promise<Snapshot> : Promise.reject(new Error('snapshot ' + r.status)))
}

const SVG_W = 1200
const SVG_H = 800
const SVG_MARGIN = 60

function toSigmaGraph(snap: Snapshot): Graph<GraphNode, GraphLink & { implicit?: string }> {
  const g = new Graph<GraphNode, GraphLink & { implicit?: string }>({ multi: true })
  const pts = circularLayout(snap.nodes.map(n => n.id), SVG_W, SVG_H, SVG_MARGIN)
  for (const n of snap.nodes) {
    const p = pts.get(n.id) ?? { x: SVG_W / 2, y: SVG_H / 2 }
    g.addNode(n.id, {
      ...n, x: p.x, y: p.y,
      color: colorOf(n.kind), label: n.title ?? n.kind, size: 4 + n.importance * 8,
    })
  }
  for (const l of snap.links) {
    // graphology multi: a typed key disambiguates parallel edges
    g.addEdge(l.source, l.target, { ...l, type: l.type })
  }
  return g
}

function download(filename: string, blob: Blob): void {
  const a = document.createElement('a')
  a.href = URL.createObjectURL(blob)
  a.download = filename
  a.click()
  URL.revokeObjectURL(a.href)
}

function MemoryGraphPanel(): JSX.Element {
  const [view, setView] = useState<ViewQuery>(DEFAULT_VIEW)
  const [snap, setSnap] = useState<Snapshot | null>(null)
  const [loading, setLoading] = useState(false)
  const [err, setErr] = useState<string | null>(null)
  const [tagInput, setTagInput] = useState('')
  const [views, setViews] = useState<SavedView[]>(() => loadViews(window.localStorage))
  const [viewName, setViewName] = useState('')
  const containerRef = useRef<HTMLDivElement>(null)
  const sigmaRef = useRef<any>(null)

  const reload = () => {
    setLoading(true); setErr(null)
    fetchSnapshot(view).then(s => { setSnap(s); setLoading(false) }).catch(e => { setErr(String(e?.message ?? e)); setLoading(false) })
  }

  useEffect(() => { reload() }, [view])

  // (re)render sigma whenever the snapshot changes
  useEffect(() => {
    if (!snap || !containerRef.current) return
    sigmaRef.current?.kill?.()
    const g = toSigmaGraph(snap)
    const sigma = new Sigma(g, containerRef.current, {
      defaultNodeColor: '#94a3b8',
      defaultEdgeColor: '#475569',
      labelThreshold: 10,
      renderEdgeLabels: false,
      defaultNodeSize: 6,
    })
    sigma.on('clickNode', ({ node }: { node: string }) => {
      setView(v => ({ ...v, focus: v.focus === node ? null : node }))
    })
    sigmaRef.current = sigma
    return () => sigma.kill?.()
  }, [snap])

  const toggleImplicit = () => setView(v => ({ ...v, implicitEdges: !v.implicitEdges }))
  const toggleTombstoned = () => setView(v => ({ ...v, hideTombstoned: !v.hideTombstoned }))

  const exportJSON = () => {
    if (!snap) return
    download('memory-graph.json', new Blob([JSON.stringify(snap, null, 2)], { type: 'application/json' }))
  }

  const exportSVG = () => {
    if (!snap) return
    const pts = circularLayout(snap.nodes.map(n => n.id), SVG_W, SVG_H, SVG_MARGIN)
    const nodes = snap.nodes.map(n => {
      const p = pts.get(n.id) ?? { x: SVG_W / 2, y: SVG_H / 2 }
      return { id: n.id, x: p.x, y: p.y, label: n.title ?? n.kind, color: colorOf(n.kind), size: 4 + n.importance * 8 }
    })
    try {
      const svg = toSVG(nodes, snap.links.map(l => ({
        source: l.source, target: l.target,
        color: l.implicit ? '#334155' : '#64748b', dashed: !!l.implicit,
      })), { width: SVG_W, height: SVG_H, background: '#0f172a' })
      download('memory-graph.svg', new Blob([svg], { type: 'image/svg+xml' }))
    } catch (e) {
      setErr(String(e?.message ?? e))
    }
  }

  const applyTagInput = () => {
    const tags = tagInput.split(',').map(t => t.trim()).filter(Boolean)
    setView(v => ({ ...v, tags }))
  }

  const doSaveView = () => {
    try {
      setViews(saveView(window.localStorage, viewName, view))
      setViewName('')
    } catch (e) {
      setErr(String(e?.message ?? e))
    }
  }

  const legend = useMemo(() => Object.entries(KIND_COLOR), [])

  return (
    <section style={{ padding: 12 }}>
      <div style={{ marginBottom: 8, fontSize: 13, color: '#94a3b8' }}>
        {(snap?.capturedAt ? 'Captured ' + snap.capturedAt : '') +
          (snap ? ' · ' + snap.nodes.length + ' nodes · ' + snap.links.length + ' edges' : '')}
        {view.focus ? ' · focus: ' + view.focus : ''}
      </div>
      <div style={{ display: 'flex', gap: 6, marginBottom: 8, flexWrap: 'wrap', alignItems: 'center' }}>
        <button style={btnStyle} onClick={reload} disabled={loading}>Refresh</button>
        <button style={{ ...btnStyle, background: view.implicitEdges ? '#3b82f6' : '#334155' }} onClick={toggleImplicit}>
          Implicit {view.implicitEdges ? 'on' : 'off'}
        </button>
        <button style={btnStyle} onClick={toggleTombstoned}>Tombstoned {view.hideTombstoned ? 'hidden' : 'shown'}</button>
        {view.focus
          ? <button style={btnStyle} onClick={() => setView(v => ({ ...v, focus: null }))}>Clear focus</button>
          : null}
        <input
          style={inputStyle}
          placeholder="tags: comma,separated"
          value={tagInput}
          onChange={e => setTagInput(e.target.value)}
          onKeyDown={e => { if (e.key === 'Enter') applyTagInput() }}
        />
        <button style={btnStyle} onClick={applyTagInput}>Filter tags</button>
        <button style={btnStyle} onClick={exportJSON} disabled={!snap}>Export JSON</button>
        <button style={btnStyle} onClick={exportSVG} disabled={!snap}>Export SVG</button>
      </div>
      <div style={{ display: 'flex', gap: 6, marginBottom: 8, flexWrap: 'wrap', alignItems: 'center' }}>
        <input
          style={inputStyle}
          placeholder="save current view as…"
          value={viewName}
          onChange={e => setViewName(e.target.value)}
          onKeyDown={e => { if (e.key === 'Enter') doSaveView() }}
        />
        <button style={btnStyle} onClick={doSaveView} disabled={!viewName.trim()}>Save view</button>
        <select
          style={inputStyle}
          value=""
          onChange={e => {
            const v = views.find(s => s.name === e.target.value)
            if (v) setView(cloneQuery(v.query))
          }}
        >
          <option value="">apply saved view…</option>
          {views.map(v => <option key={v.name} value={v.name}>{v.name}</option>)}
        </select>
        {views.length
          ? <select style={inputStyle} value="" onChange={e => { if (e.target.value) setViews(deleteView(window.localStorage, e.target.value)) }}>
              <option value="">delete saved view…</option>
              {views.map(v => <option key={v.name} value={v.name}>{v.name}</option>)}
            </select>
          : null}
      </div>
      {err ? <pre style={{ color: '#ef4444', fontSize: 12 }}>{err}</pre> : null}
      <div ref={containerRef} style={{ width: '100%', height: '640px', background: '#0f172a', borderRadius: 6 }} />
      <div style={{ display: 'flex', gap: 12, marginTop: 8, flexWrap: 'wrap', fontSize: 12, color: '#94a3b8' }}>
        {legend.map(([kind, color]) => (
          <span key={kind} style={{ display: 'inline-flex', alignItems: 'center', gap: 4 }}>
            <span style={{ width: 10, height: 10, borderRadius: 5, background: color, display: 'inline-block' }} />
            {kind}
          </span>
        ))}
        <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4 }}>
          <span style={{ width: 18, borderTop: '2px dashed #334155', display: 'inline-block' }} />
          implicit (shared entity)
        </span>
      </div>
    </section>
  )
}

const btnStyle: CSSProperties = { background: '#334155', color: '#e2e8f0', border: '1px solid #475569', borderRadius: 4, padding: '4px 10px', cursor: 'pointer', fontSize: 12 }
const inputStyle: CSSProperties = { background: '#1e293b', color: '#e2e8f0', border: '1px solid #475569', borderRadius: 4, padding: '4px 8px', fontSize: 12 }

/** Register the graph as a settings tab. */
export function apply(ctx: ClientContext): void {
  const locale = (ctx as unknown as { locale: { t?: (k: string) => string } }).locale
  const label = () => (locale?.t ? locale.t('graphTitle') : 'Memory Graph')
  ctx.slots.inject('settings.section', () => ctx.slots.register(
    { name: 'settings.section', id: 'memory-graph', order: 100, label },
    () => <MemoryGraphPanel />,
  ))
}
